import React from 'react';
import { View, Linking } from 'react-native';
import { SettingsSection, SettingItem } from './settings-section';
import { useLocaleStore } from '../../stores/locale-store';
import { NATIVE_REPO_URL } from '../../lib/about-links';
import licences from '../../lib/licences.json';
import { APP_NAME } from './AboutSettings';

/** Settings → About → Open-source licences. The list is generated by scripts/generate-licences.mjs. */
export function LicencesSettings() {
  const t = useLocaleStore((s) => s.t);
  return (
    <View style={{ gap: 24 }}>
      <SettingsSection
        title={APP_NAME}
        description={t(
          'settings.licences.app_desc',
          'The app is free software under the {licence}. You can use, study, share and change it.',
          { licence: 'GNU Affero General Public License v3.0' },
        )}
      >
        <SettingItem
          label={licences.app.license}
          description={t('settings.licences.read_licence', 'Read the full licence text')}
          onPress={() => void Linking.openURL(`${NATIVE_REPO_URL}/blob/main/LICENSE`)}
          link="external"
          noBorder
        />
      </SettingsSection>
      <SettingsSection
        title={t('settings.licences.libraries', 'Libraries')}
        description={t('settings.licences.libraries_desc', 'Open-source code the app is built with.')}
      >
        {licences.libraries.map((lib, i) => (
          <SettingItem
            key={lib.name}
            label={lib.name}
            description={lib.version ? `${lib.license} · ${lib.version}` : lib.license}
            onPress={lib.url ? () => void Linking.openURL(lib.url) : undefined}
            link="external"
            noBorder={i === licences.libraries.length - 1}
          />
        ))}
      </SettingsSection>
    </View>
  );
}
